// Typed client of the NCM Classifier API. The types come from the API's OpenAPI schema
// (src/lib/api/schema.d.ts, generated by `npm run gen:api`), so a contract change in the
// API shows up here as a type error instead of a silent bug in the browser.
import { API_URL } from "@/lib/config";

import type { components } from "./schema";

type Schemas = components["schemas"];
export type HealthResponse = Schemas["HealthResponse"];
export type ModelInfo = Schemas["ModelInfoResponse"];
export type PredictionResponse = Schemas["PredictionResponse"];
export type PredictionResult = Schemas["PredictionResult"];
export type Suggestion = Schemas["Suggestion"];
export type TestMetrics = Schemas["TestMetrics"];

const REQUEST_TIMEOUT_MS = 70_000; // a sleeping free instance takes about a minute to wake up

// Every failure the interface can show: an HTTP error in the API's standard format,
// or a request that never got an answer (offline, timeout, server waking up).
export class ApiError extends Error {
  constructor(
    message: string,
    readonly status: number | null,
    readonly code: string,
    readonly requestId: string | null = null,
    readonly retryAfterSeconds: number | null = null,
  ) {
    super(message);
    this.name = "ApiError";
  }

  // 503 (model loading) and network failures usually mean the server is still waking up.
  get isTemporary(): boolean {
    return this.status === null || this.status === 503;
  }
}

async function toApiError(response: Response): Promise<ApiError> {
  const retryAfter = Number(response.headers.get("Retry-After"));
  let body: Schemas["ErrorResponse"] | undefined;
  try {
    body = (await response.json()) as Schemas["ErrorResponse"];
  } catch {
    body = undefined;
  }
  const detail = body?.error?.details?.[0]?.message;
  return new ApiError(
    detail ?? body?.error?.message ?? `Erro HTTP ${response.status}`,
    response.status,
    body?.error?.code ?? "http_error",
    body?.error?.request_id ?? response.headers.get("X-Request-ID"),
    Number.isFinite(retryAfter) && retryAfter > 0 ? retryAfter : null,
  );
}

async function send(path: string, init?: RequestInit): Promise<Response> {
  try {
    return await fetch(`${API_URL}${path}`, {
      ...init,
      signal: init?.signal ?? AbortSignal.timeout(REQUEST_TIMEOUT_MS),
    });
  } catch (error) {
    // A cancellation by the caller is not an API failure: let it through unchanged.
    if (error instanceof DOMException && error.name === "AbortError") throw error;
    throw new ApiError("Não foi possível falar com a API.", null, "network_error");
  }
}

async function request<T>(path: string, init?: RequestInit): Promise<T> {
  const response = await send(path, init);
  if (!response.ok) throw await toApiError(response);
  return (await response.json()) as T;
}

// /health answers 503 with a health body (starting or unavailable), not an error body.
export async function getHealth(signal?: AbortSignal): Promise<HealthResponse> {
  const response = await send("/health", { signal });
  if (response.status === 200 || response.status === 503) {
    return (await response.json()) as HealthResponse;
  }
  throw await toApiError(response);
}

export function getModelInfo(signal?: AbortSignal): Promise<ModelInfo> {
  return request<ModelInfo>("/v1/model", { signal });
}

export function predict(descriptions: string[], signal?: AbortSignal): Promise<PredictionResponse> {
  const body = descriptions.length === 1 ? { description: descriptions[0] } : { descriptions };
  return request<PredictionResponse>("/v1/predictions", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(body),
    signal,
  });
}
